// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint64 number, uint64 timestamp, uint256 basefee, bytes32 hash, uint64 seq, bytes32 batcher, uint256 overhead, uint256 scalar) public {
        vm.assume(actor != address(0));
        address before = c.depositorAccount();
        vm.prank(actor);
        bool ok;
        try c.setL1BlockValues(number, timestamp, basefee, hash, seq, batcher, overhead, scalar) {
            ok = true;
        } catch {
            ok = false;
        }
        // General rule: for every admissible input, setL1BlockValues never alters
        // the observable depositorAccount value, regardless of whether the call
        // succeeds or reverts. The mutant stores msg.sender into depositorAccount,
        // so when its call succeeds (ok == true) the getter returns `actor`,
        // breaking the invariant for some fuzzed caller.
        assertTrue(c.depositorAccount() == before);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(
        address actor,
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public {
        // Wide admissible domain: all block-value parameters are unconstrained.
        address initialDepositor = c.depositorAccount();

        // 1. Authorized call: the caller allowed by c's own public access rule
        //    (read from c's public surface, not hard-coded).
        address authorized = c.DEPOSITOR_ACCOUNT();
        vm.prank(authorized);
        try c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar) {
            // a successful call must still leave depositorAccount untouched
        } catch {
            // reverting is also acceptable for the reference
        }

        // 2. Arbitrary fuzzed caller.
        vm.prank(actor);
        try c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar) {
            // no-op
        } catch {
            // no-op
        }

        // General rule: no call to setL1BlockValues, succeeding or reverting,
        // from any caller, ever changes depositorAccount().
        assertTrue(c.depositorAccount() == initialDepositor);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function test(uint64 _number) external {
        (bool ok, ) = address(c).call(
            abi.encodeCall(
                C.setL1BlockValues,
                (_number, 0, 0, bytes32(0), 0, bytes32(0), 0, 0)
            )
        );
        assert(ok == (msg.sender == c.depositorAccount()));
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function testNonDepositorCanSet(uint64 n, uint64 t, uint256 f, bytes32 h, uint64 s, bytes32 b, uint256 o, uint256 sc, address caller) external {
        require(caller != c.depositorAccount());
        bool ok = true;
        (bool success, ) = address(c).call(
            abi.encodeWithSelector(
                c.setL1BlockValues.selector,
                n, t, f, h, s, b, o, sc
            )
        );
        ok = success;
        assert(ok);
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint64 number_, uint64 timestamp_, uint256 basefee_, bytes32 hash_, uint64 seq_, bytes32 batcherHash_, uint256 overhead_, uint256 scalar_) public {
        require(address(c).depositorAccount() != address(this));
        bool reverted;
        try c.setL1BlockValues(number_, timestamp_, basefee_, hash_, seq_, batcherHash_, overhead_, scalar_) { reverted = false; } catch { reverted = true; }
        assert(reverted);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint64 _number, uint64 _timestamp, uint256 _basefee, bytes32 _hash, uint64 _sequenceNumber, bytes32 _batcherHash, uint256 _l1FeeOverhead, uint256 _l1FeeScalar) public {
        require(msg.sender != c.depositorAccount(), "caller must not be the depositor account");
        bool reverted;
        try c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar) { reverted = false; } catch { reverted = true; }
        assert(!reverted);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        bool reverted;
        address depositor = c.depositorAccount();
        if (msg.sender != depositor) {
            try c.setL1BlockValues(1, 1, 1, bytes32(0), 1, bytes32(0), 1, 1) { reverted = false; } catch { reverted = true; }
            assert(reverted);
        }
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        bool reverted;
        try c.setL1BlockValues(1, 1, 1, bytes32(0), 1, bytes32(0), 1, 1) { reverted = false; } catch { reverted = true; }
        assert(reverted == (address(this) == c.depositorAccount()));
    }
    receive() external payable {}
}

